INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(44611, 'Exodus 26:35', 'Exodus', 26, 35, 'هغه مېز د پردې څخه دباندې د خېمې شمال خواته کېږده او څراغدان ورته مخامخ جنوب خواته کېږده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_35.mp3', '', 1761754199, 1761754199),
(44612, 'Exodus 26:36', 'Exodus', 26, 36, 'د خېمې د دروازې دپاره د ابي، بانجاني او سرو وړیو او د ښه کتان څخه یوه پرده جوړه کړه چې ګلدوزي شوې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_36.mp3', '', 1761754199, 1761754199),
(44613, 'Exodus 26:37', 'Exodus', 26, 37, 'د دغې پردې دپاره د سرو زرو چنګکونه جوړ کړه او د اکاسۍ د لرګي څخه پنځه داسې ستنې جوړې کړه چې د سرو زرو پوښ ورته ورکړل شوی وي. د هغو دپاره پنځه برنجي پایې جوړې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus26_verse_37.mp3', '', 1761754199, 1761754199),
(44614, 'Judges 7:1', 'Judges', 7, 1, 'یوه ورځ سهار وختي جدعون د خپلو ټولو کسانو سره پاڅېده، هغوی لاړل او د حرود د چینې په خوا کې یې خېمې ودرولې. د مدیانیانو کمپ د هغوی شمال خواته د موره غره ته نژدې په یوه دره کې ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_1.mp3', '', 1761754199, 1761754199),
(44615, 'Judges 7:2', 'Judges', 7, 2, 'څښتن جدعون ته وویل: «ستا کسان ډېر زیات دي. که چېرې تاسو ټول پرېږدم چې د مدیانیانو سره وجنګېږئ او هغوی ته ماتې ورکړئ، نو بیا به اسراییلیان لافې وهي او وایي به چې مونږ په خپل زور خپل ځانونه ژغورلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_2.mp3', '', 1761754199, 1761754199),
(44616, 'Judges 7:3', 'Judges', 7, 3, 'نو خلکو ته اعلان وکړه او ووایه چې هرڅوک چې ډارن وي او د جنګ څخه وېریږي، هغه دې بېرته کور ته لاړ شي او مونږ به دلته د جلعاد په غره کې پاتې شو.» نو دوه ویشت زره کسان بېرته لاړل او یوازې لس زره کسان پاتې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_3.mp3', '', 1761754199, 1761754199),
(44617, 'Judges 7:4', 'Judges', 7, 4, 'څښتن جدعون ته وویل: «ستا کسان اوس هم زیات دي. هغوی ښکته چینې ته بوځه او هلته به هغوی ستا دپاره بېل کړم. زه به تاته ووایم چې څوک درسره لاړ شي او څوک بېرته کور ته لاړ شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_4.mp3', '', 1761754199, 1761754199),
(44618, 'Judges 7:5', 'Judges', 7, 5, 'کله چې جدعون خپل سړي لاندې اوبو ته بوتلل، څښتن هغه ته وویل: «سړي په دوو ډلو ووېشه. په یوه ډله کې هغه ټول ونیسه چې اوبه د لاسونو په لپو کې را اخلي او په خپلو ژبو یې لکه د سپیانو په شان څټي. په بله ډله کې هغه ټول ونیسه چې زنګنونه لاندې لګوي او د ویالې څخه اوبه په خپلو خولو څښي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_5.mp3', '', 1761754199, 1761754199),
(44619, 'Judges 7:6', 'Judges', 7, 6, 'یوازې درې سوو سړیو یې په لاسونو اوبه وڅښلې. نورو ټولو خپل زنګنونه لاندې ولګول او اوبه یې د ویالې نه په خولو وڅښلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_6.mp3', '', 1761754199, 1761754199),
(44620, 'Judges 7:7', 'Judges', 7, 7, 'څښتن جدعون ته وویل: «زه به په دغو درې سوه کسانو چې اوبه یې وڅټلې، تاسو وژغورم او مدیانیان به درته تسلیم کړم. نور ټول کسان پرېږده چې خپلو کورونو ته لاړ شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_7.mp3', '', 1761754199, 1761754199),
(44621, 'Judges 7:8', 'Judges', 7, 8, 'نو جدعون یوازې درې سوه کسان د ځان سره وساتل او د پاتې کسانو څخه یې خواړه او سرني راټول کړل او هغوی یې خپلو کورونو ته رخصت کړل. د مدیانیانو کمپ د هغوی څخه لاندې په دره کې ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_8.mp3', '', 1761754199, 1761754199),
(44622, 'Judges 7:9', 'Judges', 7, 9, 'هغه شپه څښتن په جدعون باندې حکم وکړ: «پاڅه او د مدیانیانو په کمپ باندې حمله وکړه، زه تاته په هغوی باندې بری درکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_9.mp3', '', 1761754199, 1761754199),
(44623, 'Judges 7:10', 'Judges', 7, 10, 'خو که چېرې ته د حملې کولو څخه وېرېږې، نو د خپل نوکر فوره سره کمپ ته ورښکته شه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_10.mp3', '', 1761754199, 1761754199),
(44624, 'Judges 7:11', 'Judges', 7, 11, 'نو ته به د مدیانیانو خبرې واورې چې څه وایي. وروسته به جرات پیدا کړې چې په کمپ باندې حمله وکړې.» نو هغه د خپل نوکر سره د کمپ پوستې ته ښکته شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_11.mp3', '', 1761754199, 1761754199),
(44625, 'Judges 7:12', 'Judges', 7, 12, 'مدیانیان، عمالیقیان او د دښتې د قبیلو خلک لکه د ملخانو په شان په دره کې خپاره شوي وو او هغوی د بحیرې د شګو په شان بې شمېره اوښان درلودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_12.mp3', '', 1761754199, 1761754199),
(44626, 'Judges 7:13', 'Judges', 7, 13, 'کله چې جدعون هلته ورسېده، هغه واورېدل چې یو کس خپل ملګري ته خپل خوب بیانوي. هغه ویل: «ما خوب ولیده چې د اوربشو یوه ډوډۍ راغله او زمونږ په کمپ باندې راورغړېدله. خېمه یې ووهله او هغه راچپه شوه او په ځمکه باندې هواره شوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_13.mp3', '', 1761754199, 1761754199),
(44627, 'Judges 7:14', 'Judges', 7, 14, 'د هغه ملګري په ځواب کې وویل: «ستا خوب یوازې یوه معنی لري او هغه دا چې د اسراییلي یوآش زوی جدعون د تورې سره راځي. خدای هغه ته په مدیانیانو او زمونږ په ټولو لښکرو باندې بری ورکړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_14.mp3', '', 1761754199, 1761754199),
(44628, 'Judges 7:15', 'Judges', 7, 15, 'کله چې جدعون دا خوب او د هغه تعبیر واورېده، هغه په سجده پرېوت او د څښتن عبادت یې وکړ. بیا هغه بېرته د اسراییلو کمپ ته ستون شو او غږ یې وکړ: «پاڅئ! څښتن تاسو ته د مدیانیانو په لښکرو باندې بری درکړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_15.mp3', '', 1761754199, 1761754199),
(44629, 'Judges 7:16', 'Judges', 7, 16, 'هغه دا درې سوه کسان په درېو ډلو ووېشل او هر یو ته یې یو سرنی او یو خالي منګی چې څراغ په کې ؤ، ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_16.mp3', '', 1761754199, 1761754199),
(44630, 'Judges 7:17', 'Judges', 7, 17, 'او هغوی ته یې وویل: «کله چې زه کمپ ته ورنژدې شوم، نو ماته ګورئ، هرڅه چې زه کوم، تاسو هم همداسې وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_17.mp3', '', 1761754199, 1761754199),
(44631, 'Judges 7:18', 'Judges', 7, 18, 'کله چې ما او زما ډلې سرني ووهل، تاسو هم د کمپ په شاوخوا کې سرني ووهئ او چیغې ووهئ: ‹مونږ د څښتن او جدعون دپاره جنګېږو.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_18.mp3', '', 1761754199, 1761754199),
(44632, 'Judges 7:19', 'Judges', 7, 19, 'جدعون د خپلو سلو کسانو سره د نیمې شپې څخه مخکې د مدیانیانو د کمپ څنډې ته ورسېده، په هماغه وخت کې پهره بدله شوې وه. دوی سرني ووهل او هغه منګي چې په لاسونو کې یې وو، هغه یې مات کړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_19.mp3', '', 1761754199, 1761754199),
(44633, 'Judges 7:20', 'Judges', 7, 20, 'او نورو دوو ډلو هم همداسې وکړل. هغوی ټولو په خپلو چپو لاسونو کې څراغونه نیولي وو او په ښي لاسونو کې یې سرني نیولي وو او چیغې یې وهلې: «د څښتن او د جدعون دپاره توره!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_20.mp3', '', 1761754199, 1761754199),
(44634, 'Judges 7:21', 'Judges', 7, 21, 'هغوی ټول په خپل ځای د کمپ شاوخوا کې ولاړ وو او د دښمن ټولو لښکرو چیغې وهلې او وتښتېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_21.mp3', '', 1761754199, 1761754199),
(44635, 'Judges 7:22', 'Judges', 7, 22, 'په داسې حال کې چې د جدعون کسانو سرني وهل، څښتن د دښمنانو لښکرې په خپل منځ کې سره په جنګ اخته کړلې او هغوی په یو بل باندې په تورو باندې حمله وکړه. هغوی د بیت شطه څخه د صریرت خواته د ابل محولا پورې چې طبات ته نژدې ؤ، وتښتېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_22.mp3', '', 1761754199, 1761754199),
(44636, 'Judges 7:23', 'Judges', 7, 23, 'بیا جدعون د نفتالي او اشیر قبیلو او د ټول منسي څخه کسان راوغوښتل او هغوی راغلل او په مدیانیانو پسې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_23.mp3', '', 1761754199, 1761754199),
(44637, 'Judges 7:24', 'Judges', 7, 24, 'هغه د افرایم ټولې غرنۍ سیمې ته استازي ولېږل چې هغوی ته ووایي: «راښکته شئ او د مدیانیانو په وړاندې وجنګېږئ. د اردن سیند او ویالې تر بیت باره پورې ونیسئ، ترڅو مدیانیان ورڅخه تېر نه شي.» نو د افرایم ټول کسان راټول شول او تر بیت باره پورې یې د اردن سیند او ویالې ونیولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_24.mp3', '', 1761754199, 1761754199),
(44638, 'Judges 7:25', 'Judges', 7, 25, 'هغوی د مدیانیانو دوه مشران چې غراب او زیب نومېدل، ونیول. غراب یې د غراب په ګټ وواژه او زیب یې د انګورو د شربت ویستلو په خم کې چې د زیب په نوم یادېده، وواژه. دوی د مدیانیانو تعقیبولو ته دوام ورکړ او د غراب او زیب سرونه یې د اردن د سیند په ختیځ کې جدعون ته راوړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges7_verse_25.mp3', '', 1761754199, 1761754199),
(44639, 'Psalms 18:1', 'Psalms', 18, 1, 'ته زما قوت یې ای څښتنه په ما ګران یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_1.mp3', '', 1761754199, 1761754199),
(44640, 'Psalms 18:2', 'Psalms', 18, 2, 'څښتن دی زما ساتونکی دی زما قوي کلا زما ژغورونکی زما خدای دی زما امن دی هغه کې کوي ساتنه زما لکه د سپر په شان دی زما قوي ژغورونکی او د امن پناه ځای دی زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_2.mp3', '', 1761754199, 1761754199),
(44641, 'Psalms 18:3', 'Psalms', 18, 3, 'مرسته غواړم له څښتنه چې لایق دی د صفت خلاصوي مې هغه ما له خپلو دښمنانو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_3.mp3', '', 1761754199, 1761754199),
(44642, 'Psalms 18:4', 'Psalms', 18, 4, 'د مرګ رسۍ رانه راتاوې شولې د بربادۍ سېلابو واخیستمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_4.mp3', '', 1761754199, 1761754199),
(44643, 'Psalms 18:5', 'Psalms', 18, 5, 'د ګور په لومه کې راګېر یمه زه مرګ راته لاره کې خپل دام ایښی ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_5.mp3', '', 1761754199, 1761754199),
(44644, 'Psalms 18:6', 'Psalms', 18, 6, 'په خپل تکلیف کې مې څښتن ته غږ کړ کومک دپاره مې خپل خدای ته غږ کړ زما اواز یې په خپل کور کې واورېد زما فریاد یې د کومک واورېده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_6.mp3', '', 1761754199, 1761754199),
(44645, 'Psalms 18:7', 'Psalms', 18, 7, 'بیا ځمکې وخوړ ټکان ولړزېدله خوځېدل د غرو بېخونه په لړزه شول ځکه په قهر ؤ خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_7.mp3', '', 1761754199, 1761754199),
(44646, 'Psalms 18:8', 'Psalms', 18, 8, 'شو له سپېږمو نه یې راپورته لوګی بلې لمبې او سرې سکروټې یې بادېدلې د خولې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_8.mp3', '', 1761754199, 1761754199),
(44647, 'Psalms 18:9', 'Psalms', 18, 9, 'ده کړې خلاصې دروازې د اسمانونو او راښکته شو تورې ورېځې وې د ده تر‌پښو لاندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_9.mp3', '', 1761754199, 1761754199),
(44648, 'Psalms 18:10', 'Psalms', 18, 10, 'سپور په اسماني مخلوق شو والوته سپور شو په وزرو د باد زر راغی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_10.mp3', '', 1761754199, 1761754199),
(44649, 'Psalms 18:11', 'Psalms', 18, 11, 'ځان ته جوړه یې پرده کړه له تیارې نه د اوبو ډکې ټینګې ورېځې وې چاپېره د ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_11.mp3', '', 1761754199, 1761754199),
(44650, 'Psalms 18:12', 'Psalms', 18, 12, 'جلال یې د حضور شولو ښکاره په منځ د ورېځو کې ږلۍ او سرې سکروټې ورېدې لکه باران', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_12.mp3', '', 1761754199, 1761754199),
(44651, 'Psalms 18:13', 'Psalms', 18, 13, 'لکه تندر څښتن وکړلې خبرې له اسمانه شو اواز د خدای تعالی په اورېدو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_13.mp3', '', 1761754199, 1761754199),
(44652, 'Psalms 18:14', 'Psalms', 18, 14, 'وویشتل هغه خپل غشي، دښمنان یې تار په تار کړل د برېښنا په پړکېدو یې وارخطا کړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_14.mp3', '', 1761754199, 1761754199),
(44653, 'Psalms 18:15', 'Psalms', 18, 15, 'بیا ستا په رټلو باندې ای څښتنه ستا د تنفس په انفجار سره تل د دریاب هم راښکاره شولو وو پراته د ځمکې بنیادونه لوڅ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_15.mp3', '', 1761754199, 1761754199),
(44654, 'Psalms 18:16', 'Psalms', 18, 16, 'له اسمانه څښتن لاس خپل کړ را‌اوږد ویې نیولم له ژورو اوبو ده راوویستلم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms18_verse_16.mp3', '', 1761754199, 1761754199),
