(44706, 'Numbers 33:2', 'Numbers', 33, 2, 'د څښتن په امر موسی د هغه ځای نوم لیکه چې هرځل به هغوی خپلې خېمې په کې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_2.mp3', '', 1761754199, 1761754199),
(44707, 'Numbers 33:5', 'Numbers', 33, 5, 'د اسراییلو قوم د رعمسیس څخه لاړ او په سوکوت کې یې خېمې ودرولې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_5.mp3', '', 1761754199, 1761754199),
(44708, 'Numbers 33:6', 'Numbers', 33, 6, 'او د هغه ځای څخه لاړل او په ایتام کې یې چې د دښتې په یوه څنډه کې پروت ؤ، خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_6.mp3', '', 1761754199, 1761754199),
(44709, 'Numbers 33:7', 'Numbers', 33, 7, 'د هغه ځای څخه فم الحیروت ته چې د بعل صفون په ختیځ کې ؤ، بېرته راستانه شول او مجدل ته نژدې یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_7.mp3', '', 1761754199, 1761754199),
(44710, 'Numbers 33:8', 'Numbers', 33, 8, 'هغوی د فم الحیروت څخه لاړل، د سرې بحیرې څخه تېر شول، درې ورځې یې د ایتام په دښته کې سفر وکړ او په ماره کې یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_8.mp3', '', 1761754199, 1761754199);